<?php get_header(); ?><main id="main" class="wrap collection"><?php if (is_search()) { ?><h1>Kết quả: <?php echo esc_html(get_search_query()); ?></h1><?php } elseif (is_tax()) { ?><h1><?php single_term_title(); ?></h1><?php } elseif (is_404()) { ?><h1>Không tìm thấy trang</h1><p><a href="<?php echo esc_url(home_url('/')); ?>">Trở về trang chủ</a></p><?php } ?>
<div class="<?php echo (is_search() || is_tax()) ? 'product-grid' : 'prose'; ?>"><?php if(have_posts()) { while(have_posts()) { the_post(); if(get_post_type()==='product') { techshow_card(); } else { ?><article><h1><?php the_title(); ?></h1><?php the_content(); ?></article><?php } } } elseif (!is_404()) { echo '<p>Không tìm thấy nội dung phù hợp.</p>'; } ?></div><?php the_posts_pagination(); ?></main><?php get_footer(); ?>
